steps.command:
dotnet build samples/CustomControls -c Release
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
dotnet build samples/ComplexProject -f net8.0-windows -c Debug -p:TargetFrameworks=net8.0-windows
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
dotnet build samples/ComplexProject -f net9.0-windows -c Debug -p:TargetFrameworks=net9.0-windows
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
dotnet build samples/ComplexProject -f net10.0-windows -c Debug -p:TargetFrameworks=net10.0-windows
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
dotnet build fixtures/Net48CtxFixture -c Release -p:PlatformTarget=x64
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
dotnet build fixtures/FakeVendor -c Release -p:PlatformTarget=x64
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }

for ($i = 1; $i -le 3; $i++) {
  npm audit --audit-level=moderate
  if ($LASTEXITCODE -eq 0) { exit 0 }
  if ($i -lt 3) { Start-Sleep -Seconds (10 * $i) }
}
exit 1

node ./scripts/collect-v2-test-evidence.mjs --kind=xunit "--input=$(Join-Path $env:RUNNER_TEMP 'v2-scenario-evidence/test-results/modern/modern.trx')" "--output=$(Join-Path $env:RUNNER_TEMP 'v2-scenario-evidence/xunit-modern.json')" --invocation=xunit-modern-net10
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
node ./scripts/collect-v2-test-evidence.mjs --kind=xunit "--input=$(Join-Path $env:RUNNER_TEMP 'v2-scenario-evidence/test-results/net48/net48.trx')" "--output=$(Join-Path $env:RUNNER_TEMP 'v2-scenario-evidence/xunit-net48.json')" --invocation=xunit-net48
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
node ./scripts/collect-v2-test-evidence.mjs --kind=vitest "--input=$(Join-Path $env:RUNNER_TEMP 'v2-scenario-evidence/test-results/vitest.json')" "--output=$(Join-Path $env:RUNNER_TEMP 'v2-scenario-evidence/vitest.json')" --invocation=vitest-4.1.12
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }

node --check media/designer.js
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
node --check media/panel.js
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
node --check media/chooseItems.js
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }

$evidence = Join-Path $env:RUNNER_TEMP 'release22-upgrade-evidence'
New-Item -ItemType Directory -Force -Path $evidence | Out-Null
$vsix = Join-Path $env:RUNNER_TEMP 'frozen-win32-x64.vsix'
$stable = Get-ChildItem .vscode-test -Directory -Filter 'vscode-win32-x64-archive-*' |
  ForEach-Object { $_.Name -replace '^vscode-win32-x64-archive-', '' } |
  Where-Object { $_ -ne '1.84.0' } | Sort-Object { [version]$_ } | Select-Object -Last 1
if (-not $stable) { throw 'No cached VS Code Stable build for the installed upgrade acceptance.' }
foreach ($version in @('1.84.0', $stable)) {
  npm run release22:upgrade -- "--version=$version" --baseline=18a01c096502039ea913a1e8cc2ad0d320837e35 "--new-vsix=$vsix" "--report=$(Join-Path $evidence "release22-upgrade-$version.json")"
  if ($LASTEXITCODE -ne 0) { throw "Installed upgrade/downgrade acceptance failed on VS Code $version" }
}
